export const usMarketGuides = US.filter(guide => guide.books.length > 0);
export const marketGuides = [...usMarketGuides, ...CA];
export const canadaMarketGuides = CA;
export const marketGuidePaths = [BASE_PATH, ...marketGuides.map(({ slug }) => pageUrl('', slug))];
const guidesBySlug = new Map(marketGuides.map(guide => [guide.slug, guide]));

const statusLabel = guide => ({
  statewide: 'Statewide mobile market', 'online-only': 'Online-only market', limited: 'Location-limited betting', retail: 'Retail or tribal venue only', pending: 'Launch pending', unavailable: 'No regulated sportsbook market', provincial: 'Provincially managed', atlantic: 'Atlantic Lottery market', territorial: 'Territorial lottery market', 'open-regulated': 'Regulated private-operator market',
}[guide.status] || 'Market rules vary by jurisdiction');
const oneSentence = guide => guide.country
  ? 'Canadian law lets provinces and territories conduct and manage single-event sports betting in their own jurisdictions. There is no single national sportsbook market, so local rules determine which options are available.'
  : guide.group
    ? `${guide.name} sports betting is governed through its provincial or territorial lottery and gaming framework. The official provider and its location rules are the starting point for checking legal sports betting options.`
    : guide.status === 'unavailable'
      ? `As of ${REVIEW_DATE}, ${guide.name} has no state-regulated online or retail sportsbook market. No legal state-licensed betting apps are listed for the state.`
      : guide.status === 'pending'
        ? `${guide.name} has authorized a new tribal online betting framework, but a statewide sportsbook launch had not occurred by ${REVIEW_DATE}.`
        : guide.status === 'limited'
          ? `${guide.name} sports betting is limited by physical location. The listed sportsbook options do not amount to statewide mobile access.`
          : guide.status === 'retail'
            ? `${guide.name} allows sports wagering at specified licensed or tribal venues, but does not have a statewide online sportsbook market.`
            : `${guide.name} permits legal sports betting through regulated apps and/or retail books. The exact operators, locations, eligible markets, and age rules remain subject to local regulation.`;

function marketList(guide) {
  if (guide.books?.length) return `<ul class="market-book-list">${guide.books.map(book => { const logo = brandAsset(book); return `<li${logo ? ' class="has-logo"' : ''}>${logo ? `<img src="${esc(logo)}" alt="" width="22" height="22" loading="lazy">` : ''}${esc(book)}</li>`; }).join('')}</ul>`;
  if (guide.status === 'unavailable') return '<p>No state-licensed online sportsbook operators are listed in this market snapshot. Daily fantasy, sweepstakes products, prediction contracts, and offshore sites are separate products and should not be treated as licensed state sportsbook apps.</p>';
  return '<p>A live commercial sportsbook list is not published here because this market is venue-based, pending, or managed by a provincial/territorial lottery. Use the official source linked below for current options.</p>';
}

function countryDirectory(base) {
  const country = CA.filter(guide => guide.country);
  const provinces = CA.filter(guide => !guide.country && guide.group === 'province');
  const territories = CA.filter(guide => !guide.country && guide.group === 'territory');
  const list = guides => `<div class="market-region-cards">${guides.map(guide => marketGuideCard(guide)).join('')}</div>`;
  return `<section class="market-region-section"><h2>National guide</h2>${list(country)}</section><section class="market-region-section"><h2>Provinces</h2>${list(provinces)}</section><section class="market-region-section"><h2>Territories</h2>${list(territories)}</section>`;
}

function marketGuideCard(guide) {
  const searchable = `${guide.name} ${guide.availability} ${guide.books?.join(' ') || ''} ${guide.portalName || ''}`.toLowerCase();
  const status = guide.status ? `<span class="market-state-status ${esc(guide.status)}">${esc(statusLabel(guide))}</span>` : '<span class="market-state-status provincial">Provincial guide</span>';
  return `<a class="market-guide-card" href="${BASE_PATH}/${esc(guide.slug)}" data-market-guide="${esc(searchable)}"><span class="market-guide-art longform-art--${artworkForSlug(guide.slug,true)}" style="${artStyle('state', guide.slug)}" role="img" aria-label="Editorial illustration for sports betting in ${esc(guide.name)}"></span>${status}<strong>${esc(guide.name)}</strong><small>${esc(guide.availability)}</small><span class="market-card-link">Read the location guide <span aria-hidden="true">→</span></span></a>`;
}

function stateDirectory() {
  return `<div class="market-state-grid">${usMarketGuides.map(marketGuideCard).join('')}</div>`;
}

function hubPage(base) {
  const canonical = `${base}${BASE_PATH}`;
  const description = 'Find U.S. state and Canadian province sports betting rules, legal sportsbook app availability, operators, location limits, and official regulator sources.';
  const title = 'Online Sports Betting by State & Province: Legal Sportsbooks | VisualOdds';
  const body = `<main id="main" class="edu-main market-hub"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><span>Sports betting by state</span></nav><header class="market-library-heading"><span class="eyebrow">VISUALODDS GUIDES · LOCATION-BY-LOCATION RESEARCH</span><h1>Online Sports Betting by State and Province</h1><p>Check legal sports betting availability, sportsbook operators, location limits, and official regulator sources for your state, province, or territory.</p><p class="market-library-note">Market status reviewed September 24, 2026. Always verify current rules with the linked regulator before opening an account or placing a wager.</p><a href="#us-markets">Browse location guides <span aria-hidden="true">↓</span></a></header><nav class="market-category-tabs" aria-label="Browse by country"><a href="#us-markets">United States <span>${usMarketGuides.length}</span></a><a href="#canada-markets">Canada <span>${CA.length} guides</span></a></nav><div class="market-library-toolbar"><label class="market-search-label" for="market-search">Search locations or operators</label><label class="market-search-wrap"><span aria-hidden="true">⌕</span><input class="market-search" id="market-search" type="search" placeholder="Try “Nevada” or “FanDuel”" autocomplete="off"><kbd>/</kbd></label><span class="market-result-count" aria-live="polite"><strong data-market-count>${marketGuides.length}</strong> guides</span></div><section id="us-markets" class="market-directory"><div class="guide-list-heading"><div><span class="eyebrow">UNITED STATES</span><h2>Sports betting by state</h2></div><span>${usMarketGuides.length} state guides</span></div>${stateDirectory()}</section><section id="canada-markets" class="market-directory market-canada"><div class="guide-list-heading"><div><span class="eyebrow">CANADA</span><h2>Sports betting by province and territory</h2></div><span>${CA.length} guides</span></div><p>Federal law permits provinces and territories to conduct and manage single-event sports betting. In practice, sportsbook brands and access rules depend on the local lottery or regulated market.</p>${countryDirectory(base)}</section><section class="market-method"><h2>How to use this sports betting directory</h2><p>We distinguish statewide mobile betting from an app that only works inside a casino, retail-only wagering, and a market that has been authorized but has not launched. A book named in a market report is not a live licensing guarantee. This is an editorial directory, not a sportsbook affiliate comparison or legal opinion.</p><p>VisualOdds’s U.S. comparison feed can return FanDuel, DraftKings, BetMGM, Caesars, Fanatics, and bet365 lines when its source publishes them. Its region is not verified state by state, so that supported-book list does not establish that a sportsbook is licensed or offers a price in your location. VisualOdds does not take bets.</p></section><p class="market-no-results" hidden>No location matches that search. Try another state, province, or sportsbook.</p><p class="editorial-note"><strong>Responsible play.</strong> Sports betting can cause financial harm. Set limits and stop if it no longer feels manageable. Check your local regulator for self-exclusion and support resources.</p></main>`;
  const structuredData = { '@context':'https://schema.org','@type':'CollectionPage',name:title,description,url:canonical,mainEntity:{'@type':'ItemList',numberOfItems:marketGuides.length,itemListElement:marketGuides.map((guide,index)=>({'@type':'ListItem',position:index+1,url:pageUrl(base,guide.slug),name:`Sports betting in ${guide.name}`}))}};
  return shell({ title, description, canonical, body, structuredData, directorySearch: true, marketPage: true });
}

function longFormMarketSections(guide) {
  const name = esc(guide.name);
  const country = !!guide.country;
  const canadianRegion = !!guide.group;
  const operatorNames = guide.books?.length ? guide.books.join(', ') : 'the official local provider';
  const marketOverview = country
    ? `Canada sports betting is organized by province and territory. Federal law provides a framework for provinces and territories to conduct and manage single-event sports betting, while the local regulator, lottery, or authorized private-market rules determine which sports betting apps can accept a wager. A national search result is not a substitute for checking the rules where you are physically located.`
    : canadianRegion
      ? `${name} sports betting is governed through its provincial or territorial lottery and gaming framework. This guide focuses on the local sportsbook options and rules that apply in ${name}; offers found in another province, territory, or U.S. state do not automatically apply here.`
      : `The ${name} sports betting market is defined by local law, regulator decisions, and operator approvals. People searching for ${name} sportsbooks or legal sports betting apps need to check both the market status and the specific operator: an app's national presence, download page, or odds feed does not prove that it is authorized to accept bets in ${name}.`;
  const accessExplanation = country
    ? `There is no single Canada-wide mobile sportsbook market. Ontario has a regulated private-operator market alongside OLG.ca, while many other provinces and territories use government lottery products or locally managed platforms. The province and territory guides linked on this site identify the official starting point for each area.`
    : canadianRegion
      ? `${name} availability is described as ${guide.availability.toLowerCase()}. Start with ${guide.regulator}, then follow the official portal link for account, event, and purchase-channel details. Where a province or territory relies on a lottery product, the product name is not a promise that every event, wager type, or promotional offer will be available.`
      : guide.status === 'online-only'
        ? `${name} is listed as an online-only sports betting market. That means a legal sportsbook may take eligible wagers through an approved app without a comparable state retail-book network; it does not remove location, account, age, or event restrictions.`
        : guide.status === 'limited'
          ? `${name} betting access is location-limited. A sportsbook or casino app may work only at specified licensed properties, so being inside the state is not by itself enough. Confirm the exact venue, geolocation boundary, and registration requirements before relying on an app.`
          : guide.status === 'retail'
            ? `${name} offers venue-based sports betting rather than a statewide mobile sportsbook market. The listed venues and tribal or property rules matter: retail access at one location does not mean a phone app can accept a wager from anywhere in ${name}.`
            : guide.status === 'pending'
              ? `${name} has a market change recorded as pending in this guide. Authorization, operator selection, testing, and a public launch are separate steps; do not treat an announced or authorized framework as a live sportsbook app until the official regulator confirms that wagers are being accepted.`
              : guide.slug === 'louisiana'
                ? `${name} permits online and retail wagering, with local parish permissions affecting where sports betting is allowed. Check your exact location and the operator's geolocation result; a statewide brand list does not replace a parish-level check.`
                : guide.slug === 'nevada'
                  ? `${name} has mobile and retail sportsbook options, but some operators require first-time registration at an affiliated property. Confirm whether an account can be opened remotely before planning to use a Nevada sportsbook app.`
                  : guide.slug === 'new-hampshire'
                    ? `${name} uses a single-provider model for online and retail wagering. The Lottery's rules and operator terms explain which account, location, event, and retail requirements apply.`
                    : `The guide lists ${guide.availability.toLowerCase()}. A statewide market can make approved apps available across eligible parts of ${name}, but it does not mean every operator has the same registration method, event menu, or location rules. Read the local regulator's rules and each app's terms.`;
  const operatorIntro = country
    ? `This Canada-wide overview names provincial and territorial systems rather than one set of nationwide sportsbooks. The examples below point readers toward the right local market; use the linked province or territory guide to check an individual operator, lottery product, and current account terms.`
    : canadianRegion
      ? `The sportsbook options shown for ${name} are ${operatorNames}. This is a starting list for readers looking for ${name} sportsbook apps and legal sports betting options, not a live comparison of prices, promotions, or every event market.`
      : `The market snapshot for ${name} includes ${operatorNames}. These are the sportsbook names or venue options to verify against ${guide.regulator}; the list is not a ranking and should not be read as a guarantee that every named app is accepting new customers or offering every bet type today.`;
  const marketDifferentiator = country
    ? `A useful Canada sports betting search includes a location: province and territory rules are not interchangeable. Check the provincial guide for the official app or market directory, and confirm physical-location requirements before attempting to register or place a wager.`
    : canadianRegion
      ? `When comparing ${name} sports betting options, begin with the official lottery or regulator named above. It can clarify whether the provider is government-run, part of a provincial open market, available online, or limited to a retail channel.`
      : `The phrase “legal sportsbook in ${name}” refers to an operator authorized for that jurisdiction and product. It is different from an offshore site, a daily-fantasy product, a sweepstakes promotion, or a prediction-market contract; those products can have different rules and should not be assumed to be licensed sportsbooks.`;
  const sportsContext = country
    ? `Canadian fans often search for NHL betting in Canada, hockey odds, CFL markets, NFL odds, NBA lines, or soccer betting. Those are useful sport-specific searches, but a national keyword or U.S. odds listing does not establish that a particular Canadian operator offers the event or market where you live.`
    : `Searches such as ${name} NFL betting, NBA betting apps in ${name}, ${name} MLB odds, NHL sportsbook markets, WNBA lines, or soccer betting are sport-specific. A license to operate a sportsbook does not guarantee that every operator lists every league, player prop, college event, or live market.`;
  return `<nav class="market-contents" aria-label="In this guide"><strong>In this guide</strong><a href="#market-overview">Local market</a><a href="#market-access">Online and retail access</a><a href="#sports-and-markets">Sports and bet types</a><a href="#choosing-a-sportsbook">Comparing sportsbooks</a><a href="#promotions">Promos and terms</a><a href="#verify-operator">What to verify</a></nav>
    <section id="market-overview"><h2>Sports betting in ${name}: local market overview</h2><p>${esc(marketOverview)}</p><p>${esc(marketDifferentiator)} The status and operator details on this page were reviewed on ${REVIEW_DATE}; they can change when laws, licenses, partnerships, or platform terms change.</p></section>
    <section id="market-access"><h2>Online sports betting in ${name}: apps, retail, and location access</h2><p>${esc(accessExplanation)}</p><p>Online sports betting uses an approved website or mobile app, while retail sports betting takes place at a licensed sportsbook, casino, racetrack, tribal venue, or lottery outlet where permitted. The two channels can have different operators and rules. Check the exact channel listed for ${name} instead of assuming that an app works at a retail counter or that a retail book can accept a remote mobile wager.</p><p>Sportsbook geolocation also matters. An operator can verify that a device is inside the permitted area, but that technical check does not answer every legal question about account eligibility, age, registration, or event rules. Keep location services enabled only as required by the operator and read its local terms.</p></section>
    <section id="sports-and-markets"><h2>Sports and betting markets offered in ${name}</h2><p>${esc(sportsContext)}</p><p>Depending on the operator and local rules, a sportsbook menu may include game lines, totals, moneylines, futures, live betting, parlays, and player props. Menus change by sport, event, date, and jurisdiction. A market shown in an odds comparison tool is not proof that every sportsbook in ${name} offers it or that local rules permit it.</p><p>For a practical search, pair the sport or bet type with the location, such as “NFL sportsbook in ${name}” or “${name} player prop betting rules.” Then verify the event board in an authorized app and check restrictions for college teams, player props, live markets, and postponed games.</p></section>
    <section id="choosing-a-sportsbook"><h2>How to compare the best sportsbook apps in ${name}</h2><p>There is no single best sportsbook for every reader in ${name}. A useful comparison starts with the approved operators in this guide, then looks at the sports and bet types you care about, the app's local availability, and the rules that affect how a wager is settled. A nationally familiar brand is not automatically the right or legal option for every location.</p><p>Before opening an account, compare practical details rather than a headline promotion: whether the book is listed by the local regulator, how geolocation works, which deposit and withdrawal methods are supported, how long withdrawals take under the terms, how customer support can be reached, and whether the app publishes clear settlement rules. Check the regulator's current license list if an operator name has changed or a partnership has ended.</p><p>Odds are another comparison point. If you already use a legal sportsbook, compare the same market and timestamp across available books; prices can move and different books may grade markets under different house rules. VisualOdds is a research workspace, so its data should help explain odds and markets rather than replace an operator's official terms.</p></section>
    <section id="promotions"><h2>Sports betting promos and bonus terms in ${name}</h2><p>Readers searching for ${name} sportsbook promos, betting bonuses, or promo codes should verify any offer directly with the authorized operator. Offers can vary by state or province, account status, event, and promotion dates. This guide does not list a bonus as available unless the operator's own current terms confirm it for your location.</p><p>Read the full terms before relying on a promotion. Look for eligible customers, minimum odds, qualifying stake, opt-in steps, expiration date, maximum bonus value, rollover or play-through rules, and whether the reward is cash, withdrawable winnings, or site credit. “Risk-free” and similar advertising language does not remove the possibility of losing the stake or facing restrictions.</p></section>
    <section id="verify-operator"><h2>How to verify a legal sportsbook in ${name}</h2><p>Use ${guide.regulator} as the official starting point for ${name} sportsbook laws and operator approvals. Compare a brand's full legal entity and local partner with the regulator or lottery list; a similar brand name, national license, or search-engine advertisement is not enough to establish local authorization.</p><p>Then confirm the app's exact location coverage, account eligibility, permitted event types, college and player-prop rules, bet limits, settlement policy, complaint process, and responsible-gambling tools. If the operator's terms conflict with a general market summary, follow the current official local rules and contact the regulator or lottery for clarification.</p><ul><li>Check the operator and any casino, track, tribal, or lottery partner on the official list.</li><li>Confirm that the online or retail channel is authorized where you are physically located.</li><li>Read local age, identity-verification, event, player-prop, and settlement requirements.</li><li>Review deposit limits, self-exclusion, dispute contacts, and responsible-gambling resources.</li></ul></section>`;
}

function articlePage(guide, base) {
  const canonical = pageUrl(base, guide.slug);
  const country = !!guide.country;
  const title = country ? titleFor(guide) : `${country ? 'Sports Betting in' : guide.group ? 'Sports Betting in' : 'Online Sports Betting in'} ${guide.name}: ${guide.group || guide.status === 'unavailable' || guide.status === 'retail' || guide.status === 'pending' ? 'Legal Status, Apps & Rules' : 'Legal Apps, Books & Rules'}`;
  const description = country
    ? 'A guide to legal sports betting in Canada: provincial and territorial sportsbook options, Ontario’s regulated app market, official lottery sites, and location rules.'
    : `${guide.name} sports betting laws, online sportsbook apps, licensed operators, mobile access, and official ${guide.group ? 'provincial or territorial' : 'state'} regulator sources. Reviewed September 2026.`.slice(0, 158);
  const statusText = oneSentence(guide);
  const faq = [
    { question: `Is online sports betting legal in ${guide.name}?`, answer: statusText },
    { question: `Which sportsbooks can I use in ${guide.name}?`, answer: guide.books?.length ? `${guide.name} market reporting lists ${guide.books.slice(0, 5).join(', ')}${guide.books.length > 5 ? ', and other options shown in this guide' : ''}. This is a dated market snapshot, not a real-time license feed. Check the official regulator or lottery and the operator's geolocation rules before relying on a brand list.` : `${guide.name} does not have a statewide legal online sportsbook list in this market snapshot. Check the official source for venue-based or provincial lottery options and current rules.` },
    { question: `Can I use a sportsbook app anywhere in ${guide.name}?`, answer: country || guide.group ? `Not necessarily. Players must be physically located where a platform is authorized to accept wagers, and the exact province or territory controls which account and product rules apply. Check the official local provider before using a Canada sportsbook app.` : `${guide.name} sportsbook apps can accept bets only where the operator is authorized and its location rules permit. Venue-limited books, parish rules, in-person registration, and geolocation can affect access, so confirm the exact operator and location.` },
    { question: `What sports and bet types are available in ${guide.name}?`, answer: `Sportsbook menus change by operator, event, season, and jurisdiction. NFL, NBA, WNBA, MLB, NHL, soccer, live betting, parlays, and player props may have different availability or restrictions; check the authorized operator's current event board and local rules.` },
    { question: `What is the best sportsbook app in ${guide.name}?`, answer: `There is no single best sportsbook for every person in ${guide.name}. Compare only locally authorized operators, then review the sports and bet types you use, odds, settlement terms, geolocation, payment options, support, and responsible-gambling tools.` },
    { question: `Are sportsbook promos or bonus codes available in ${guide.name}?`, answer: `Promotions vary by operator, location, account eligibility, and date. Confirm a ${guide.name} betting bonus or promo code in the sportsbook's current local terms, including the opt-in steps, minimum odds, expiration, rollover, and withdrawal rules.` },
    { question: `Does VisualOdds offer sportsbook odds in ${guide.name}?`, answer: 'VisualOdds reads a public U.S. odds comparison source that prefers FanDuel and can use DraftKings, BetMGM, Caesars, Fanatics, or bet365 as a fallback when lines are published. Its pricing region is not independently verified by state; an app or price appearing in the feed is not proof of local licensing or availability, and Canadian market prices are not provided.' },
    { question: `How current is this ${guide.name} sportsbook list?`, answer: `This editorial market snapshot was reviewed September 24, 2026; it is not a real-time operator or odds feed. Laws, licenses, products, and market access can change, so verify current sportsbook apps and rules with ${guide.regulator} before relying on the list.` },
  ];
  const sources = `<ul class="market-source-list"><li><a href="${esc(guide.regulatorUrl)}" target="_blank" rel="noopener noreferrer">${esc(guide.regulator)}</a><span>Official regulatory, lottery, or jurisdiction source</span></li>${guide.group ? country ? '' : `<li><a href="${FEDERAL_CANADA_SOURCE}" target="_blank" rel="noopener noreferrer">Government of Canada: single-event sports betting</a><span>Federal framework and provincial/territorial responsibility</span></li>` : `<li><a href="${esc(MARKET_OVERVIEW)}" target="_blank" rel="noopener noreferrer">2026 U.S. sports betting status overview</a><span>Secondary market summary reviewed September 2026; verify licensing with the regulator</span></li>`}${guide.portalUrl && guide.portalUrl !== guide.regulatorUrl ? `<li><a href="${esc(guide.portalUrl)}" target="_blank" rel="noopener noreferrer">${esc(guide.portalName || 'Official sportsbook or lottery portal')}</a><span>Current operator offerings and account terms</span></li>` : ''}</ul>`;
  const canadaContext = country || guide.group ? `<section><h2>How Canadian sports betting is organized</h2><p>Federal law provides a framework for provinces and territories to conduct and manage single-event sports betting in their jurisdictions. It does not create one nationwide roster of sportsbook apps. The province or territory, lottery, regulator, and current site terms determine which operators and markets are available.</p><p>Players must be physically located where a platform is authorized to accept wagers. Age thresholds and account rules differ by jurisdiction; confirm them directly with the official provider.</p>${country ? countryDirectory(base) : ''}</section>` : '';
  const relatedMarketGuides = marketGuides
    .filter(item => item.slug !== guide.slug && !!item.country === country && item.status === guide.status)
    .slice(0, 3);
  const relatedMarkup = relatedMarketGuides.length ? `<nav class="related" aria-label="Similar articles"><h2>Similar articles</h2><ul>${relatedMarketGuides.map(item => renderRelatedCard({
    artType: 'state',
    href: `${BASE_PATH}/${item.slug}`,
    slug: item.slug,
    category: country ? 'Canada market guide' : 'State market guide',
    title: `${item.name} sports betting apps and rules`,
    description: item.note,
    meta: 'Reviewed September 24, 2026',
  })).join('')}</ul></nav>` : '';
  const article = `<main id="main" class="edu-main market-article-page"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="${BASE_PATH}">Sports betting by state</a><span>/</span><span>${esc(guide.name)}</span></nav><article class="edu-article market-article"><div class="longform-article-grid"><header class="article-header"><span class="article-category">${country ? 'Canada' : guide.group ? 'Canada · Province or territory' : 'United States · State guide'}</span><h1>${esc(title.replace(/: .*$/, ''))}</h1><p class="article-description">${esc(description)}</p><div class="article-byline"><span>VisualOdds market guide</span><span aria-hidden="true">·</span><time datetime="${REVIEW_DATE}">Reviewed September 24, 2026</time></div></header><div class="article-content"><p class="article-lede">${esc(statusText)}</p><aside class="market-status-record"><div><span>Market status</span><strong class="market-state-status ${esc(guide.status)}">${esc(statusLabel(guide))}</strong></div><div><span>Online access</span><strong>${esc(guide.availability)}</strong></div><div><span>Official oversight</span><strong>${esc(guide.regulator)}</strong></div></aside><section><h2>${country ? 'Sportsbook options across Canada' : `${guide.name} sportsbook apps and retail options`}</h2><p>${esc(guide.note)}</p>${marketList(guide)}<p class="market-list-caveat">Operator names are a dated market snapshot, not a complete or real-time license feed. Use the official regulator or lottery source below to confirm current sportsbook apps, property partnerships, geographic limits, age eligibility, and market restrictions.</p></section>${canadaContext}<section><h2>Sportsbook data supported by VisualOdds</h2><p>VisualOdds’s research workspace covers NFL, NBA, WNBA, MLB, NHL, and soccer; schedules and available markets vary by sport and date. Its U.S. public odds comparison source may include these book labels: <strong>${SUPPORTED_FEED_BOOKS.map(esc).join(', ')}</strong>. The app prefers FanDuel and uses a named fallback only when the source has a matching line. Arizona is the preferred region, but state-specific prices are not independently verified; the feed does not provide Canadian market prices.</p><p>VisualOdds is a sports research workspace. It does not operate a sportsbook, accept deposits, or place wagers.</p></section><section><h2>Rules to verify before using a sportsbook</h2><ul><li>Confirm the operator appears on the current official license or lottery list for your jurisdiction.</li><li>Check that the app permits wagers from your exact physical location; casino- and tribal-property apps may be tightly geofenced.</li><li>Read local age, event, college, player-prop, and settlement rules in the official terms.</li><li>Review deposit limits, self-exclusion, and the local responsible-gambling resources before creating an account.</li></ul></section><section class="market-sources"><h2>Official regulator and market sources</h2>${sources}</section><section class="faq market-faq"><h2>Frequently asked questions</h2>${faq.map(item=>`<details><summary>${esc(item.question)}</summary><p>${esc(item.answer)}</p></details>`).join('')}</section><aside class="editorial-note"><strong>Information, not legal advice.</strong> Laws, operator approvals, and market availability can change. This guide is a research starting point, not an endorsement or instruction to bet. Sports betting involves financial risk.</aside></div></div>${relatedMarkup}<nav class="article-pagination" aria-label="Guide navigation"><a href="${BASE_PATH}">← All state and province guides</a><a href="/research">Explore VisualOdds research</a></nav></article></main>`;
  const expandedArticle = article.replace('<section><h2>Sportsbook data supported by VisualOdds</h2>', `${longFormMarketSections(guide)}<section><h2>Sportsbook data supported by VisualOdds</h2>`);
  const contentMatch = expandedArticle.match(/<div class="article-content">([\s\S]*)<\/div>\s*<\/div>(?=\s*(?:<nav class="related"|<nav class="article-pagination"))/);
  const presentation = prepareLongformContent(contentMatch?.[1] || '', guide.slug, title, { artType: 'state' });
  const formattedArticle = expandedArticle.replace(/<div class="article-content">([\s\S]*)<\/div>\s*<\/div>(?=\s*(?:<nav class="related"|<nav class="article-pagination"))/, (_match, inner) => `<div class="article-content">${presentation.html}</div></div>`)
    .replace('</time></div></header>', `</time><span aria-hidden="true">·</span><span class="article-reading-time">${readingTimeLabel(presentation.minutes)}</span></div></header>`)
    .replace('class="edu-article market-article"', 'class="edu-article market-article has-longform"');
  const articleSchema = { '@context':'https://schema.org','@type':'Article',headline:title,description,wordCount:presentation.wordCount,datePublished:REVIEW_DATE,dateModified:CONTENT_UPDATED_DATE,mainEntityOfPage:canonical,author:{'@type':'Organization',name:'VisualOdds Editorial'},publisher:{'@type':'Organization',name:'VisualOdds',url:base}};
  const faqSchema = { '@context':'https://schema.org','@type':'FAQPage',mainEntity:faq.map(item=>({'@type':'Question',name:item.question,acceptedAnswer:{'@type':'Answer',text:item.answer}}))};
  const breadcrumb = {'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:base},{'@type':'ListItem',position:2,name:'Sports betting by state',item:`${base}${BASE_PATH}`},{'@type':'ListItem',position:3,name:guide.name,item:canonical}]};
  return shell({ title:`${title} | VisualOdds`, description, canonical, body:formattedArticle, structuredData:[articleSchema,faqSchema,breadcrumb], marketPage: true });
}

function shell({ title, description, canonical, body, structuredData, directorySearch = false, marketPage = false }) {
  const themeColor = marketPage ? '#f4f3ed' : '#080d12';
  const bodyClass = marketPage ? ' class="market-guide-site"' : '';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="${themeColor}"><meta name="description" content="${esc(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${esc(canonical)}"><meta property="og:type" content="article"><meta property="og:site_name" content="VisualOdds"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${esc(canonical)}"><title>${esc(title)}</title><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/InterVariable.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/betting-education.css"><link rel="stylesheet" href="/online-sports-betting.css"><link rel="stylesheet" href="/longform-articles.css?v=20260926-toc-bold"><script type="application/ld+json">${JSON.stringify(structuredData).replace(/</g,'\\u003c')}</script>${directorySearch ? '<script type="module" src="/market-guide-search.js"></script>' : ''}${marketPage ? '<script type="module" src="/longform-articles.js"></script>' : ''}<link rel="stylesheet" href="/content-2026.css?v=1">${siteChromeAssets()}</head><body${bodyClass}><a class="skip-link" href="#main">Skip to content</a>${siteHeader({ current: 'learn' })}${body}${siteFooter()}</body></html>`;
}

export function renderMarketGuidePage(pathname, request) {
  const base = siteUrl(request);
  const normalized = pathname.replace(/\/$/, '') || '/';
  if (normalized === BASE_PATH) return hubPage(base);
  const match = normalized.match(/^\/online-sports-betting\/([a-z0-9-]+)$/);
  if (!match) return null;
  const guide = guidesBySlug.get(match[1]);
  return guide ? articlePage(guide, base) : null;
}

export function renderMarketGuideSitemapEntries(request) {
  const base = siteUrl(request);
  return [BASE_PATH, ...marketGuides.map(guide => `${BASE_PATH}/${guide.slug}`)].map(path => `<url><loc>${esc(`${base}${path}`)}</loc><lastmod>${CONTENT_UPDATED_DATE}</lastmod></url>`).join('');
}

export function isMarketGuidePath(pathname) {
  return pathname === BASE_PATH || pathname.startsWith(`${BASE_PATH}/`);
}
